26: /// Persistent on-disk cache for [`SsaFunction`] values.
27: pub struct SsaCache {
28:     cache_dir: PathBuf,
29: }
30: 
31: impl SsaCache {
32:     /// Create a cache rooted at `cache_dir`. The directory is created
33:     /// lazily on the first successful `put`; `new` itself performs no I/O.
34:     pub fn new(cache_dir: PathBuf) -> Self {
35:         Self { cache_dir }
36:     }
37: 
38:     /// Compute the on-disk path for an entry.
39:     fn entry_path(&self, binary_hash: u64, func_addr: u64) -> PathBuf {
40:         self.cache_dir
41:             .join(format!("{:016x}", binary_hash))
42:             .join(format!("{:016x}.bin", func_addr))
43:     }
44: 
45:     /// Look up a cached `SsaFunction`. Returns `None` on miss, I/O error,
46:     /// or decode failure (treating a corrupt cache as a miss).
47:     pub fn get(&self, binary_hash: u64, func_addr: u64) -> Option<SsaFunction> {
48:         let path = self.entry_path(binary_hash, func_addr);
49:         let bytes = fs::read(&path).ok()?;
50:         let config = bincode::config::standard();
51:         let (func, _len) =
52:             bincode::serde::decode_from_slice::<SsaFunction, _>(&bytes, config).ok()?;
53:         Some(func)
54:     }
55: 
56:     /// Store `func` under `(binary_hash, func_addr)`. Failures (e.g. the
57:     /// destination directory cannot be created, the encode fails, or the
58:     /// write fails) are silently swallowed — the cache is an optimisation,
59:     /// not a source of correctness.
60:     pub fn put(&self, binary_hash: u64, func_addr: u64, func: &SsaFunction) {
61:         let path = self.entry_path(binary_hash, func_addr);
62:         let Some(parent) = path.parent() else {
63:             return;
64:         };
65:         if fs::create_dir_all(parent).is_err() {
66:             return;
67:         }
68:         let config = bincode::config::standard();
69:         let Ok(bytes) = bincode::serde::encode_to_vec(func, config) else {
70:             return;
71:         };
72:         let _ = fs::write(&path, bytes);
73:     }
74: }
